const rows = $input.all();

if (!rows || rows.length === 0) {
  throw new Error('Aucune donnée trouvée. Assurez-vous d\'avoir soumis des questions à l\'étape 5.');
}

const question = rows[0].json.question;
const date = new Date(rows[0].json.date).toLocaleDateString('fr-FR');

let responsesText = '';
for (const row of rows) {
  if (row.json.provider && row.json.reponse) {
    responsesText += `\n\n### ${row.json.provider}\n${row.json.reponse}`;
  }
}

const metaPrompt = `Tu es un expert en évaluation de modèles de langage.
Analyse les réponses suivantes de plusieurs LLMs à la même question et génère un rapport comparatif structuré en Markdown.

## Question posée
"${question}"
(posée le ${date})

## Réponses des modèles${responsesText}

## Rapport demandé
Génère un rapport Markdown avec les sections suivantes :
1. **Résumé exécutif** : Quelle réponse est la meilleure globalement ?
2. **Analyse par critère** :
   - Précision factuelle
   - Clarté et lisibilité
   - Complétude
   - Style et ton
3. **Classement des modèles** (du meilleur au moins bon) avec justification
4. **Recommandation** : Quel modèle utiliser pour ce type de question ?

Sois objectif, précis et concis.`;

return [{ json: { metaPrompt, question, responseCount: rows.filter(r => r.json.provider).length } }];

const analysis = $input.first().json;
const question = $('Build Meta Prompt (RAG)').first().json.question;
const now = new Date().toISOString();

const report = {
  title: 'Rapport d\'analyse comparative LLM',
  generated_at: now,
  question: question,
  analysis: analysis.text || analysis.output || analysis.response,
  metadata: {
    analyzer: 'Ollama Mistral (Meta-LLM)',
    method: 'RAG - Retrieval Augmented Generation'
  }
};

return [{ json: report }];
